<script>
(()=>{const header=document.querySelector('.site-header');const syncHeader=()=>header?.classList.toggle('is-scrolled',scrollY>24);syncHeader();addEventListener('scroll',syncHeader,{passive:true});
const notices=[...document.querySelectorAll('.announcement div>span')];let notice=0;const showNotice=index=>{if(!notices.length)return;notices[notice].classList.remove('is-active');notice=(index+notices.length)%notices.length;notices[notice].classList.add('is-active')};document.querySelector('[data-notice-prev]')?.addEventListener('click',()=>showNotice(notice-1));document.querySelector('[data-notice-next]')?.addEventListener('click',()=>showNotice(notice+1));if(notices.length>1&&!matchMedia('(prefers-reduced-motion: reduce)').matches)setInterval(()=>showNotice(notice+1),4000);
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const searchDrawer=document.getElementById('search-drawer'),searchInput=document.getElementById('global-search'),searchResults=document.getElementById('predictive-search');document.getElementById('open-search')?.addEventListener('click',()=>{searchDrawer.showModal();setTimeout(()=>searchInput?.focus(),50)});document.getElementById('close-search')?.addEventListener('click',()=>searchDrawer.close());searchDrawer?.addEventListener('click',event=>{if(event.target===searchDrawer)searchDrawer.close()});let searchTimer;searchInput?.addEventListener('input',()=>{clearTimeout(searchTimer);const query=searchInput.value.trim();if(query.length<2){searchResults.innerHTML='';return}searchResults.innerHTML='<p>Mencari…</p>';searchTimer=setTimeout(async()=>{try{const response=await fetch(@json(route('search.suggestions'))+'?q='+encodeURIComponent(query),{headers:{Accept:'application/json'}});const data=await response.json();searchResults.innerHTML=data.products.length?data.products.map(item=>`<a href="${esc(item.url)}"><img src="${esc(item.image)}" alt=""><span><b>${esc(item.name)}</b><small>${esc(item.price)}</small></span><i>→</i></a>`).join(''):'<p>Produk tidak ditemukan.</p>'}catch(error){searchResults.innerHTML='<p>Pencarian belum dapat dimuat.</p>'}},250)});
const cartDrawer=document.getElementById('cart-drawer'),cartLines=document.getElementById('cart-drawer-lines'),cartFooter=document.getElementById('cart-drawer-footer');document.querySelector('[data-open-cart]')?.addEventListener('click',async event=>{if(!cartDrawer?.showModal)return;event.preventDefault();cartDrawer.showModal();cartLines.innerHTML='<p>Memuat keranjang…</p>';cartFooter.hidden=true;try{const response=await fetch(@json(route('cart.summary')),{headers:{Accept:'application/json'}});const data=await response.json();cartLines.innerHTML=data.lines.length?data.lines.map(line=>`<a class="cart-drawer-line" href="${esc(line.url)}"><img src="${esc(line.image)}" alt=""><span><b>${esc(line.name)}</b><small>${esc(line.variant)} · ${line.quantity} item</small><strong>${esc(line.total)}</strong></span></a>`).join(''):'<div class="drawer-empty"><p>Keranjang Anda masih kosong.</p><a href="{{ route('catalog') }}">MULAI BELANJA →</a></div>';if(data.lines.length){document.getElementById('cart-drawer-subtotal').textContent=data.subtotal;cartFooter.hidden=false}}catch(error){cartLines.innerHTML='<p>Keranjang belum dapat dimuat. <a href="{{ route('cart') }}">Buka halaman keranjang</a>.</p>'}});document.querySelector('[data-close-cart]')?.addEventListener('click',()=>cartDrawer.close());cartDrawer?.addEventListener('click',event=>{if(event.target===cartDrawer)cartDrawer.close()});
const quickDialog=document.getElementById('quick-product-dialog'),quickOptions=document.getElementById('quick-product-options'),quickVariant=document.getElementById('quick-variant'),quickSubmit=document.getElementById('quick-submit');let quickData=null,quickSelected={};const renderQuick=()=>{const kinds=[...(quickData.usesType?[['type','JENIS PRODUK']]:[]),['color','WARNA'],['size','UKURAN']];quickOptions.innerHTML=kinds.map(([kind,label])=>{const values=[...new Set(quickData.variants.map(item=>item[kind]).filter(Boolean))];return `<fieldset><legend>${label}</legend><div>${values.map(value=>{const possible=quickData.variants.some(item=>item.available>0&&item[kind]===value&&kinds.every(([other])=>other===kind||!quickSelected[other]||item[other]===quickSelected[other]));return `<button type="button" data-quick-kind="${kind}" data-quick-value="${esc(value)}" class="${quickSelected[kind]===value?'is-active':''}" ${possible?'':'disabled'}>${esc(value)}</button>`}).join('')}</div></fieldset>`}).join('');const match=quickData.variants.find(item=>item.available>0&&kinds.every(([kind])=>item[kind]===quickSelected[kind]));quickVariant.value=match?.id||'';quickSubmit.disabled=!match;document.getElementById('quick-product-price').textContent=match?new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(match.price):'Pilih opsi yang tersedia';quickOptions.querySelectorAll('[data-quick-kind]').forEach(button=>button.addEventListener('click',()=>{quickSelected[button.dataset.quickKind]=button.dataset.quickValue;renderQuick()}))};document.querySelectorAll('[data-quick-open]').forEach(button=>button.addEventListener('click',()=>{quickData=JSON.parse(document.getElementById(button.dataset.quickOpen).textContent);quickSelected={};document.getElementById('quick-product-name').textContent=quickData.name;document.getElementById('quick-product-image').src=quickData.image;document.getElementById('quick-product-image').alt=quickData.name;document.getElementById('quick-product-link').href=quickData.url;renderQuick();quickDialog.showModal()}));document.querySelector('[data-quick-close]')?.addEventListener('click',()=>quickDialog.close());quickDialog?.addEventListener('click',event=>{if(event.target===quickDialog)quickDialog.close()});
const observer='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12}):null;document.querySelectorAll('.reveal').forEach(element=>observer?observer.observe(element):element.classList.add('is-visible'));
const slides=[...document.querySelectorAll('[data-hero-slide]')],dots=[...document.querySelectorAll('[data-hero-dot]')];let active=0,timer;const show=index=>{active=(index+slides.length)%slides.length;slides.forEach((slide,i)=>{slide.classList.toggle('is-active',i===active);slide.setAttribute('aria-hidden',i===active?'false':'true')});dots.forEach((dot,i)=>dot.classList.toggle('is-active',i===active))};const autoplay=()=>{if(slides.length>1&&!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>show(active+1),6500)};dots.forEach(dot=>dot.addEventListener('click',()=>{clearInterval(timer);show(Number(dot.dataset.heroDot));autoplay()}));autoplay();
document.querySelectorAll('[data-drag-scroll]').forEach(track=>{let down=false,startX=0,startLeft=0;track.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse'){down=true;startX=event.clientX;startLeft=track.scrollLeft;track.classList.add('is-dragging')}});addEventListener('pointerup',()=>{down=false;track.classList.remove('is-dragging')});track.addEventListener('pointermove',event=>{if(down)track.scrollLeft=startLeft-(event.clientX-startX)})});})();
</script>
@stack('scripts')
</body>
